using Microsoft.ML.Data;

namespace ChurnPredictor;

public class CustomerData
{
    [LoadColumn(0)]
    public float Age { get; set; }

    [LoadColumn(1)]
    public float Income { get; set; }

    [LoadColumn(2)]
    public string Region { get; set; } = string.Empty;

    [LoadColumn(3)]
    public float PurchaseHistory { get; set; }

    [LoadColumn(4)]
    [BooleanType]
    public bool Churned { get; set; }
}

public class ChurnPrediction
{
    [ColumnName("PredictedLabel")]
    public bool PredictedLabel { get; set; }

    [ColumnName("Probability")]
    public float Probability { get; set; }

    [ColumnName("Score")]
    public float Score { get; set; }
}

using Microsoft.ML;

namespace ChurnPredictor;

public static class ChurnModelTrainer
{
    public static ITransformer TrainAndSave(string dataPath, string modelPath, ILogger logger)
    {
        var mlContext = new MLContext(seed: 42);

        var data = mlContext.Data.LoadFromTextFile<CustomerData>(
            dataPath, hasHeader: true, separatorChar: ',');

        var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2);

        var pipeline = mlContext.Transforms.CopyColumns("Label", nameof(CustomerData.Churned))
            .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region)))
            .Append(mlContext.Transforms.Concatenate("Features",
                nameof(CustomerData.Age),
                nameof(CustomerData.Income),
                nameof(CustomerData.PurchaseHistory),
                "RegionEncoded"))
            .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression());

        var model = pipeline.Fit(split.TrainSet);

        var predictions = model.Transform(split.TestSet);
        var metrics = mlContext.BinaryClassification.Evaluate(predictions);

        logger.LogInformation("Model Evaluation Metrics:");
        logger.LogInformation("  Accuracy: {Accuracy:F4}", metrics.Accuracy);
        logger.LogInformation("  AUC:      {Auc:F4}", metrics.AreaUnderRocCurve);
        logger.LogInformation("  F1 Score: {F1:F4}", metrics.F1Score);

        mlContext.Model.Save(model, data.Schema, modelPath);
        logger.LogInformation("Model saved to {ModelPath}", modelPath);

        return model;
    }
}

