using Microsoft.Extensions.ML;
using Microsoft.ML;
using ChurnPredictor;

var builder = WebApplication.CreateBuilder(args);

var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "customers.csv");
var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "churn_model.zip");

// Train and save the model at startup
var startupLogger = LoggerFactory.Create(b => b.AddConsole()).CreateLogger("Startup");
ChurnModelTrainer.TrainAndSave(dataPath, modelPath, startupLogger);

// Register PredictionEnginePool (thread-safe for ASP.NET Core)
builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
    .FromFile(modelPath);

var app = builder.Build();

app.MapGet("/", () => "Hello");

app.MapPost("/predict", (PredictRequest request,
    PredictionEnginePool<CustomerData, ChurnPrediction> predictionPool) =>
{
    var input = new CustomerData
    {
        Age = request.Age,
        Income = request.Income,
        Region = request.Region,
        PurchaseHistory = request.PurchaseHistory
    };

    var prediction = predictionPool.Predict(input);

    return Results.Ok(new
    {
        willChurn = prediction.PredictedLabel,
        probability = prediction.Probability
    });
});

app.Run();

record PredictRequest(float Age, float Income, string Region, float PurchaseHistory);

